def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal bands: fill blank rows by repeating the colors of the
    # final two nonblank rows, while preserving all existing bands.
    band_rows = []
    bands = True
    for r, row in enumerate(grid):
        if all(v == 0 for v in row):
            continue
        if len(set(row)) != 1:
            bands = False
            break
        band_rows.append((r, row[0]))

    if bands and len(band_rows) >= 2:
        a, b = band_rows[-2][1], band_rows[-1][1]
        out = [row[:] for row in grid]
        for r in range(h):
            if all(v == 0 for v in grid[r]):
                color = a if r % 2 == 0 else b
                out[r] = [color] * w
        return out

    # Otherwise, extend the anti-diagonal color pattern periodically.
    cells = [(r + c, grid[r][c])
             for r in range(h) for c in range(w) if grid[r][c] != 0]
    for period in range(1, min(h + w, 30) + 1):
        mapping = {}
        valid = True
        for s, color in cells:
            k = s % period
            if k in mapping and mapping[k] != color:
                valid = False
                break
            mapping[k] = color
        if valid and len(mapping) > 1:
            out = [[mapping.get((r + c) % period, 0) for c in range(w)]
                   for r in range(h)]
            return out

    return [row[:] for row in grid]
