def transform(grid):
    h, w = len(grid), len(grid[0])

    # Each candidate key describes a family of parallel stripes:
    # horizontal, vertical, and the two diagonal orientations.
    candidates = [
        (lambda r, c: r),
        (lambda r, c: c),
        (lambda r, c: r + c),
        (lambda r, c: c - r),
    ]

    for key_fn in candidates:
        groups = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    groups.setdefault(key_fn(r, c), []).append(color)

        # A stripe direction is plausible when its observed stripes are
        # monochromatic and at least one stripe has multiple cells.
        if not groups or any(len(set(vals)) != 1 for vals in groups.values()):
            continue
        repeated = sum(len(vals) for vals in groups.values() if len(vals) > 1)
        if repeated == 0:
            continue

        stripe_colors = {k: vals[0] for k, vals in groups.items()}
        max_key = max(abs(key_fn(r, c)) for r in range(h) for c in range(w))

        period = None
        pattern = None
        for p in range(1, max_key + 2):
            trial = {}
            valid = True
            for k, color in stripe_colors.items():
                residue = k % p
                if residue in trial and trial[residue] != color:
                    valid = False
                    break
                trial[residue] = color
            if valid:
                period, pattern = p, trial
                break

        if period is None:
            continue

        return [
            [pattern.get(key_fn(r, c) % period, 0) for c in range(w)]
            for r in range(h)
        ]

    return [row[:] for row in grid]
